UND=[['拉丁 unda → undare','波浪 → 起浪、涌流']]
ABOUND=UND+[['拉丁 ab- + undare → abundare → 古法语 abonder → 英语 abound','向外涌、满出来 → 大量存在']]
ABUNDANT=UND+[['拉丁 abundare → abundans；法语 abundant → 英语 abundant','满溢的 → 充足、大量的']]
ABUNDANCE=UND+[['拉丁 abundare → abundantia；古法语 abondance → 英语 abundance','满溢 → 充足的数量、丰富']]
REDUNDANT=UND+[['拉丁 re(d)- + undare → redundare → redundans → 英语 redundant','又涌出、满溢 → 超出需要、多余']]
INUND=UND+[['拉丁 in- + undare → inundare','涌上来、漫过 → 淹没']]
UNDUL=UND+[['与小波形式 undula 相连的拉丁 undulatus','波浪状、起伏的；近代英语借用这一词族']]
W += [
E('abound','/əˈbaʊnd/','大量存在；充满','数量多到像水满出来，随处都能见到。','拉丁 ab- 向外 + undare 起浪 → abundare，经过法语 abonder；不是 a- 加 bound 边界。',ABOUND,'opportunities abound 是机会很多；a region abounds in wildlife 是当地野生动物丰富。现代多用作不及物动词。','abound in；abound with；rumours/opportunities abound。','have 很普通；abound 强调很多，带一点书面色彩。不要把它和 be bound to 必然混为一谈。',('Small cafés abound in the old part of town.','城镇老区里随处可见小咖啡馆。'),('The lake abounds with fish.','湖里鱼类丰富。'),sources=['https://www.etymonline.com/word/abound','https://en.wiktionary.org/wiki/abound#English']),
E('abundant','/əˈbʌndənt/','丰富的；充足的；大量的','不只是刚刚够，而是手头或周围有很多。','拉丁 abundans 是 abundare 的分词，经法语或直接借入；与 abound 同源，不是现代英语简单换尾巴。',ABUNDANT,'abundant evidence 是大量证据；abundant rainfall 是充沛降雨。它只说数量多，是否有益要看对象。','abundant resources；abundant evidence；an abundant supply。','sufficient 表示够用；abundant 通常多得充足。scarce 则说稀缺。',('The region has abundant sunshine throughout the year.','这个地区全年阳光充足。'),('There is abundant evidence that the building was used as a warehouse.','有大量证据表明这座建筑曾被用作仓库。'),sources=['https://www.etymonline.com/word/abundant','https://en.wiktionary.org/wiki/abundant#English']),
E('abundance','/əˈbʌndəns/','丰富；充足；大量','把拥有很多的状态或那一大批东西作为名词来讲。','拉丁 abundantia 经法语 abondance 等借入；现代可与 abundant 对照，但名词有自己的借入线。',ABUNDANCE,'an abundance of fruit 是大量水果；in abundance 是充足地、大量地。an abundance of caution 是格外谨慎这一固定说法，不是真数有多少份谨慎。','an abundance of；in abundance；an abundance of caution。','abundant 是形容词，abundance 是名词；plenty 更日常，abundance 更常见于书面描述。',('The market offered an abundance of fresh vegetables.','市场上新鲜蔬菜供应充足。'),('Wildflowers grew in abundance along the path.','小路边长着大量野花。'),sources=['https://www.etymonline.com/word/abundance','https://en.wiktionary.org/wiki/abundance#English']),
E('abundantly','/əˈbʌndəntli/','大量地；充足地；十分明显地','可以说东西长得很多，也可以把清楚、明显的程度推得很高。','abundant + -ly；副词继承丰富、充分的核心。',ABUNDANT+[['英语 abundant + -ly → abundantly','充足的 → 大量地、充分地']],'grow abundantly 是大量生长；abundantly clear 是非常清楚。后者是程度搭配，不是有很多个清楚。','abundantly clear；abundantly obvious；grow abundantly。','abundantly 常与 clear、obvious 配合加强语气；不能随意替换每一个 very。',('These plants grow abundantly in damp woodland.','这些植物在潮湿林地里大量生长。'),('She made it abundantly clear that the deadline would not change.','她说得非常清楚，截止日期不会变。'),sources=['https://en.wiktionary.org/wiki/abundantly#English','https://www.oxfordlearnersdictionaries.com/definition/english/abundantly']),
E('overabundance','英 /ˌəʊvərəˈbʌndəns/；美 /ˌoʊvərəˈbʌndəns/','过量；过剩；多得过头','东西本来多是好事，现在却超过了需要，带来负担。','over- 过度 + abundance；英语内部形成，较早英语已有对应形式。',ABUNDANCE+[['英语 over- + abundance → overabundance','丰富 → 过多、过剩']],'an overabundance of choices 是选项太多；an overabundance of detail 会把重点淹没。over- 明确加上超过合适程度的评价。','an overabundance of；an overabundance of information；an overabundance of caution。','abundance 只说丰富，常偏正面；overabundance 明确说多过头。',('An overabundance of options made the menu confusing.','选项过多，让菜单看起来令人困惑。'),('The report suffers from an overabundance of minor details.','报告里琐碎细节太多，影响了整体效果。'),sources=['https://www.collinsdictionary.com/dictionary/english/overabundance','https://en.wiktionary.org/wiki/overabundance#English']),
E('redundant','/rɪˈdʌndənt/','多余的；重复不必要的；备用冗余的；被裁撤的','超出了当前必需的一份；有时是浪费，有时却是故意留的备用。','拉丁 redundans 来自 redundare 再涌出、满溢；现代直接借入形成多余义。',REDUNDANT,'a redundant sentence 可删掉而不损失信息；redundant servers 可在一台出故障时接替工作。英式 be made redundant 说因岗位不再需要而被裁员，不是在评价这个人的价值。','make redundant；redundant information；redundant systems。','duplicate 只说重复；redundant 常强调不必需或作为备用。dismissed 的离职原因可能不同，不能都当作岗位裁撤。',('The editor removed several redundant sentences.','编辑删掉了几句多余的话。'),('The system has redundant power supplies to improve reliability.','这个系统配有备用电源，以提高可靠性。'),('Several staff members were made redundant after the office closed.','办公室关闭后，几名员工因岗位撤销而被裁员。'),sources=['https://www.etymonline.com/word/redundant','https://en.wiktionary.org/wiki/redundant#English','https://www.oxfordlearnersdictionaries.com/definition/english/redundant']),
E('redundancy','/rɪˈdʌndənsi/','冗余；重复多余；岗位裁撤','说超出必需部分的状态；技术里能用来保底，工作里也可能指岗位取消。','redundant + -cy，词尾 -ant 对应 -ancy；英语构成的名词。',REDUNDANT+[['英语 redundant → redundancy','多余、备用 → 冗余状态；后来也用于岗位裁撤']],'build redundancy into a system 是设计备用能力；reduce redundancy in writing 是减少赘余。英式 redundancy payments 是裁员相关补偿，不是重复支付。','system redundancy；remove redundancy；voluntary redundancy；redundancy payments。','backup 可指一份备份或备用物；redundancy 更常说整体设计中保留的重复能力，范围不只文件备份。',('The network was designed with enough redundancy to survive a single failure.','网络设计保留了足够冗余，使其能应对单点故障。'),('The announcement included plans for voluntary redundancy.','公告包含了让员工自愿接受裁员的方案。'),sources=['https://www.etymonline.com/word/redundancy','https://www.oxfordlearnersdictionaries.com/definition/english/redundancy']),
E('inundate','/ˈɪnʌndeɪt/','淹没；使应接不暇','水、邮件或请求一下涌来，多到眼前被覆盖，来不及处理。','接拉丁 inundare / inundatus；也有从较早英语 inundation 反构的解释，不能把词源路线只画成英语动词先于名词。',INUND+[['两种解释：拉丁 inundatus 借入；或英语 inundation 反构 → inundate','被水漫过 → 淹没；大量事务涌来']],'be inundated with emails 是邮件多得应接不暇；floodwater inundates a town 则是真正淹水。with 后面通常说明涌来的东西。','inundate with；be inundated with requests；inundate low ground。','flood 既可真实也可比喻，较日常；inundate 常强调覆盖面积或数量造成的压力。',('The office was inundated with requests after the announcement.','公告发出后，办公室收到了大量请求，应接不暇。'),('Floodwater inundated the fields beside the river.','洪水淹没了河边的田地。'),sources=['https://www.etymonline.com/word/inundate','https://www.oxfordlearnersdictionaries.com/definition/english/inundate']),
E('inundation','/ˌɪnʌnˈdeɪʃən/','洪水淹没；大量涌入','把水漫过土地、事情接连涌来的整个过程当成一个名词。','拉丁 inundatio 经法语或直接借入，英语记录早于现代动词 inundate；现代对应 -ate / -ation 不等于历史先动词后名词。',INUND+[['拉丁 inundatio；法语 inundacion → 英语 inundation','洪水漫过、淹没的过程；英语名词较早出现']],'coastal inundation 是沿海地区被水淹没；an inundation of calls 是电话大量涌入。较 flood 更正式，常见于报告。','coastal inundation；the risk of inundation；an inundation of requests。','inundation 指淹没或涌入，infiltration 是渗透、进入；水一下漫过与逐渐渗入不是同一个画面。',('The map shows areas at risk of coastal inundation.','地图显示了可能遭受海水淹没的地区。'),('An inundation of applications overwhelmed the small admissions team.','申请大量涌入，让规模不大的招生团队忙不过来。'),sources=['https://www.etymonline.com/word/inundation','https://www.oxfordlearnersdictionaries.com/definition/english/inundation','https://en.wiktionary.org/wiki/inundation#English']),
E('undulate','/ˈʌndʒəleɪt/；亦美 /ˈʌndəleɪt/','起伏；呈波浪状；波动','一段高、一段低，像波浪一样连着变化。','来自 undulatus 波浪状的一系；英语动词也有从较早 undulation 或形容词 undulate 形成的解释。',UNDUL+[['英语 undulation／形容词 undulate；动词 undulate','名词、形容词较早；动词表示起伏，不硬排成现代动词先行']],'hills undulate 是丘陵绵延起伏；fabric undulates 是布料随风呈波浪般摆动。可以说形状，也可以说运动。','undulate gently；undulate in the breeze；undulating hills。','wave 可以是单次挥动或波动；undulate 更强调连续、平滑的高低变化。',('The grass undulated in the wind.','草在风中起伏，像一片波浪。'),('The road undulates through the countryside.','道路在乡间高低起伏地延伸。'),sources=['https://www.etymonline.com/word/undulate','https://www.oxfordlearnersdictionaries.com/definition/english/undulate','https://en.wiktionary.org/wiki/undulate#English']),
E('undulation','/ˌʌndʒəˈleɪʃən/','波动；起伏；波浪形曲线','把一连串高低变化，或其中的一道起伏，单独拿出来看。','接后期拉丁 undulatus 及中世纪拉丁 undulatio 一系；部分词源书将中转名词标作重建形式。英语名词早于常用动词 undulate。',UNDUL+[['中世纪拉丁 undulatio 一系','部分来源将拉丁中转名词写作 *undulatio，表示重建形式'],['英语 undulation','波浪形状、起伏运动；早于常用动词 undulate']],'the undulation of a surface 是表面起伏；gentle undulations 可指几道缓缓的高低变化。不是每一次价格小涨跌都自然叫 undulation。','gentle undulations；the undulation of；surface undulation。','fluctuation 泛指变化波动；undulation 更让人想到连续的波浪形状或运动。',('The path followed the gentle undulations of the hillside.','小路沿着山坡缓缓起伏。'),('The camera captured the slow undulation of the ribbon.','相机拍下了丝带缓慢起伏的样子。'),sources=['https://www.etymonline.com/word/undulation','https://www.oxfordlearnersdictionaries.com/definition/english/undulation','https://en.wiktionary.org/wiki/undulation#English']),
E('redound','/rɪˈdaʊnd/','产生影响；带来某种结果，尤指增光或有利','一件事做出来，结果又回到某个人或团体身上，增加名誉或好处。','拉丁 redundare 满溢、涌回，经法语 redonder；与 redundant 同源，但各自走出不同现代义。',UND+[['拉丁 redundare → 古法语 redonder → 英语 redound','满溢、涌回 → 影响归于某方、带来结果']],'redound to someone’s credit 是为某人增光；redound to the benefit of 是带来好处。属于较正式书面用法，重点学 to 后接结果或受益方。','redound to somebody’s credit；redound to the benefit of；redound to the honour of。','rebound 常说反弹；redound 常说产生归属于某方的影响。不要按拼写把它当成重新绕圆。',('The team’s generosity redounded to the credit of the whole school.','团队的慷慨行为为全校增了光。'),('The improvements should redound to the benefit of local residents.','这些改善应能让当地居民受益。'),sources=['https://www.etymonline.com/word/redound','https://www.oxfordlearnersdictionaries.com/definition/english/redound']),
]
