VESTV=V+[['中古拉丁 vestire；法语 vestir / vester → 英语 vest〔动词〕','像给人穿上衣服一样赋予财产、权利或权力']]
INV=V+[['拉丁 in- + vestire → investire；法语／拉丁语 → 英语 invest','给人披上衣服、职服 → 赋予职位、权力'],['金融义的同源支线：意大利 investire 的特殊用法，很可能影响英语 invest','给资本一种新形式 → 投入资金以求收益；后来也投入时间、精力']]
DIV=V+[['古法语 desvestir → 法语 devester → 英语 devest / divest','脱去、剥去 → 使失去财产、权力；后来也指出售资产']]
W += [
E('vest','/vest/','背心、马甲；汗衫〔英〕；授予、归属〔动词〕','衣服穿到谁身上，权力或权益也可以像衣服一样归到谁名下。','名词经法语 veste 等接拉丁 vestis；动词经法语 vestir / 中古拉丁 vestire，英语动词比现代衣物名词更早，不从名词硬推全部用法。',V+[['名词线：意大利 veste → 法语 veste → 英语 vest','衣物；现代英美指称有所不同'],['并列动词线：法语 vestir / vester、中古拉丁 vestire → 英语 vest','使拥有、授予；与名词共享更早衣服词源']],'美式 vest 常是外穿马甲，英式日常也指贴身背心。权力用法中，vest authority in someone 是把权力授予某人；be vested with authority 是被赋予权力。','a life vest；a woollen vest；vest power in；be vested with。','英式 waistcoat 常对应美式 vest；动词 vest 讲权利归属，与穿哪件衣服无关，只保留历史上的赋予联想。',('He wore a warm vest under his shirt.','他在衬衫里面穿了一件保暖背心。'),('The charter vests decision-making authority in the elected council.','章程将决策权授予民选委员会。'),sources=['https://www.etymonline.com/word/vest','https://www.oxfordlearnersdictionaries.com/definition/english/vest_1','https://www.oxfordlearnersdictionaries.com/definition/english/vest_2']),
E('vested','/ˈvestɪd/','已归属的；既得的；被赋予的','某项权利已落在某人身上，或者某人已经与一件事有直接利益关系。','vest + -ed；过去分词作形容词，接权利归属、赋予这一动词支线。',VESTV+[['英语 vest + -ed → vested','被赋予、已归属的；在 vested interest 中表示直接利益关系']],'vested rights 是既得权利；a vested interest in an outcome 是结果直接关系到自己的利益。权益已归属与是否能立即兑换、出售不是同一层意思。','vested rights；vested benefits；a vested interest in。','invested 常说投入了金钱或感情；vested 更常说权利已归属或有直接利益。',('The agreement protects employees’ vested benefits.','协议保护员工已经归属的福利权益。'),('The supplier has a vested interest in keeping the old system.','这家供应商在保留旧系统这件事上有直接利益。'),sources=['https://www.collinsdictionary.com/dictionary/english/vested','https://www.oxfordlearnersdictionaries.com/definition/english/vested-interest','https://www.oxfordlearnersdictionaries.com/definition/english/vest_2']),
E('vesting','/ˈvestɪŋ/','权益归属；权利逐步确定的过程','合同先写着将来可能得到，达到约定条件后，相应权益才正式归你。','vest + -ing；在雇佣、股权等语境里名词化，表示权益归属的过程或安排。',VESTV+[['英语 vest + -ing → vesting','使权利归属 → 权益归属安排']],'a vesting schedule 规定权益何时归属，可能分阶段或到某一时点。股票、期权和退休金安排的具体权利不同，vesting 不自动等于现金已经到账。','a vesting schedule；the vesting period；vesting conditions。','grant 是授予某项奖励或安排；vesting 是满足条件后相应权益归属。期权归属也不等于已经行权买到股票。',('The offer includes a vesting schedule for the share award.','录用方案包含了这项股份奖励的归属时间表。'),('She asked how leaving early would affect the vesting of her benefits.','她询问提前离职会怎样影响福利权益的归属。'),sources=['https://www.collinsdictionary.com/dictionary/english/vesting','https://www.oxfordlearnersdictionaries.com/definition/english/vest_2']),
E('invest','/ɪnˈvest/','投资；投入时间、精力；赋予权力或特质','把资源放进一件事里，希望它以后带来价值；也保留把权力赋予某人的正式用法。','拉丁 investire 含 in- + vestire 穿衣。金融义很可能受同源意大利 investire 影响，不能编成古人把钱穿在身上就叫投资。',INV,'invest in a business 是向企业投资；invest time in learning 是把时间花在学习上。invest someone with authority 则是赋予权力，不是给他买股份。','invest money in；invest time in；invest in equipment；invest with authority。','spend 只说花费；invest 强调投入后期待未来价值，但这个词本身不保证回报。',('The company invested in more efficient equipment.','公司投入资金购置了更高效的设备。'),('She invested a great deal of time in learning the language.','她投入了大量时间学习这门语言。'),sources=['https://www.etymonline.com/word/invest','https://www.oxfordlearnersdictionaries.com/definition/english/invest']),
E('investment','/ɪnˈvestmənt/','投资；投入；投资项目或资产','可以是投入资源的动作，也可以是投入出去的那笔钱或买下的资产。','invest + -ment；早期也与授予职位、披上职服有关，现代主要保留金融及时间精力投入义。',INV+[['英语 invest + -ment → investment','投入的行为；后来也指所投金额、项目或资产']],'investment in training 是培训投入；an investment 可以是一项投资资产。a good investment of time 强调时间花得值得，并不一定涉及钱。','investment in；public investment；an initial investment；an investment of time。','expense 说支出，investment 强调对未来价值的期待；asset 是持有的资产，未必正在发生新的投入。',('The new library represents a major investment in public education.','新图书馆代表了对公共教育的一项重大投入。'),('Learning to type well was a useful investment of time.','花时间练好打字很值得。'),sources=['https://www.etymonline.com/word/investment','https://www.etymonline.com/word/invest','https://www.oxfordlearnersdictionaries.com/definition/english/investment']),
E('investor','英 /ɪnˈvestə/；美 /ɪnˈvestər/','投资者；投资机构','拿出资金参与项目或持有资产，希望得到回报的一方。','invest + -or；施事名词可以指个人，也可以指机构。',INV+[['英语 invest + -or → investor','投资 → 提供投资资金的一方']],'an individual investor 是个人投资者；an institutional investor 是机构投资者。投入多少、怎么参与、持有多久，需要另外说明。','attract investors；an institutional investor；a private investor。','donor 提供捐助，通常不索取投资回报；investor 则带投资目的。shareholder 是股东，只涵盖持有股份的情况。',('The founders presented their plan to potential investors.','创办人向潜在投资者介绍了计划。'),('The report explains the project’s risks to investors.','报告向投资者说明了项目风险。'),sources=['https://www.etymonline.com/word/investor','https://www.oxfordlearnersdictionaries.com/definition/english/investor']),
E('investing','/ɪnˈvestɪŋ/','投资活动；正在投入','把 invest 看作持续进行的活动，而不是单独一笔金额。','invest + -ing；既是现在分词，也可名词化为投资活动。',INV+[['英语 invest + -ing → investing','投资、投入 → 持续的活动或过程']],'learn about investing 是了解投资活动；be investing in training 是正在投入培训。作为活动名词时通常不加复数。','long-term investing；investing in people；learn about investing。','investment 可指一项具体投资或资产；investing 更侧重在做投资这件事。',('The course explains the basic vocabulary of investing.','课程解释了投资活动中的基本词汇。'),('The firm is investing more time in staff training.','公司正在为员工培训投入更多时间。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/invest','https://en.wiktionary.org/wiki/investing#English']),
E('invested','/ɪnˈvestɪd/','已投入的；投入感情、很在意的；被赋予的','钱或时间已经放进去了，感情也可能跟着放进去，因此很在乎结果。','invest + -ed；过去分词作形容词，情感投入是资源投入的引申。',INV+[['英语 invest + -ed → invested','已经投入；引申为投入感情、关心结果的']],'money invested in a project 是投进项目的钱；be emotionally invested in a story 是感情上投入，关心故事走向。be invested with authority 又是被赋予权力。','emotionally invested in；heavily invested in；capital invested；invested with authority。','interested 表示感兴趣；invested 通常更有投入，结果与自己的情绪、资源或努力相连。',('The report shows how the invested funds were used.','报告说明了已投入资金的使用情况。'),('By the final episode, I was deeply invested in the characters’ lives.','看到最后一集时，我已经非常关心这些角色的命运。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/invest','https://en.wiktionary.org/wiki/invested#English']),
E('reinvest','/ˌriːɪnˈvest/','再投资；把收益重新投入','赚到或收回的钱先不拿走，再放回某项事业或资产里。','re- 再次 + invest；英语内部形成，重音仍主要落在 -vest。',INV+[['英语 re- + invest → reinvest','投入 → 再次投入']],'reinvest profits in the business 是将利润再投入企业；reinvest proceeds 是把所得款重新投资。可以投回原处，也可以另作投资。','reinvest profits；reinvest earnings；reinvest in the business。','save 是存下；reinvest 明确说重新投入。再投资不保证新一轮结果与上一轮相同。',('The shop reinvested its profits in better equipment.','商店把利润重新投入，购置了更好的设备。'),('They decided to reinvest the proceeds in another project.','他们决定把所得款再投入另一个项目。'),sources=['https://www.etymonline.com/word/reinvest','https://www.oxfordlearnersdictionaries.com/definition/english/reinvest']),
E('reinvestment','/ˌriːɪnˈvestmənt/','再投资；收益的重新投入','把资源再放回生产或项目中的行为，以及这类投入安排。','re- + investment；也可与 reinvest + -ment 对照。',INV+[['英语 investment；re- + investment → reinvestment','投资 → 再投资、重新投入']],'reinvestment of profits 是利润再投入；a reinvestment plan 是再投资安排。词义重点是再次投放，并非单纯把钱从一账户移到另一账户。','reinvestment of profits；a reinvestment plan；continued reinvestment。','reinvestment 是过程或安排，return 是回报；有回报后是否再投入，是另一件事。',('Continued reinvestment helped modernize the workshop.','持续的再投入帮助车间实现了现代化。'),('The report separates new funding from the reinvestment of earlier profits.','报告区分了新筹资金和先前利润的再投入。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/reinvestment','https://en.wiktionary.org/wiki/reinvestment#English']),
E('divest','/daɪˈvest/；亦 /dɪˈvest/','出售、剥离资产；使失去；摆脱','把原本附在身上的东西拿掉：可以是财产、职位权力，也可以是旧习惯。','法语 desvestir / devester 接 vestir 穿衣，含去除的 des-；英语先写 devest，后变 divest。',DIV,'divest a subsidiary 是出售或剥离子公司；divest someone of authority 是剥夺某人的权力。现代资金语境里经常和 invest 形成投入、退出的对照。','divest assets；divest a business；divest oneself of；divest somebody of authority。','sell 只是卖；divest 常强调从组织或持有范围里退出、剥离。不是每次出售一件日用品都需要这个正式词。',('The group decided to divest its retail division.','集团决定出售零售业务部门。'),('The reform divested the office of several former powers.','改革取消了该职位原先拥有的几项权力。'),sources=['https://www.etymonline.com/word/divest','https://en.wiktionary.org/wiki/divest#English','https://www.oxfordlearnersdictionaries.com/definition/english/divest']),
E('divestment','/daɪˈvestmənt/','撤资；资产出售、剥离','把已经持有的资产或投资退出，作为一项行动来讲。','divest + -ment；现代常见于企业重组、投资组合或某种撤资行动。',DIV+[['英语 divest + -ment → divestment','剥离、出售 → 撤资、资产剥离的行为']],'divestment from an industry 是撤出某行业投资；divestment of a business 是出售业务。动机可能是重组、财务安排或价值立场，词本身不限定一种。','divestment from；divestment of assets；a divestment programme。','investment 是投入；divestment 是退出或剥离。donation 是捐赠，不是同一种资金动作。',('The company announced the divestment of its overseas retail business.','公司宣布出售海外零售业务。'),('The committee discussed divestment from several industries.','委员会讨论了从几个行业撤资的问题。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/divestment','https://en.wiktionary.org/wiki/divestment#English']),
E('investiture','英 /ɪnˈvestɪtʃə/；美 /ɪnˈvestɪtʃər/','授职仪式；授勋仪式','通过公开仪式，把职位、荣誉或相应标志正式交到一个人身上。','中古拉丁 investitura 接 investire 穿上职服、授予；经法语或直接借入。不是现代金融 investment 的加长形式。',V+[['拉丁 investire → 中古拉丁 investitura；法语 investiture → 英语 investiture','披上职位标志 → 授职、授勋的仪式']],'an investiture ceremony 是授职或授勋典礼。历史上服饰和徽章可代表身份，所以穿上的动作也成了授予职位的名称。','an investiture ceremony；attend an investiture；the investiture of。','appointment 说任命本身；investiture 特别指正式赋予职位或荣誉的仪式。investment 常用来谈投资。',('The investiture ceremony took place in the main hall.','授职仪式在大厅举行。'),('Her family attended the investiture at which she received the honour.','她的家人参加了她接受荣誉的授勋典礼。'),sources=['https://www.etymonline.com/word/investiture','https://www.oxfordlearnersdictionaries.com/definition/english/investiture','https://en.wiktionary.org/wiki/investiture#English']),
E('vestment','/ˈvestmənt/','宗教礼服；祭服','在宗教仪式中穿戴、带有特定身份和仪式意义的服装。','拉丁 vestimentum 来自 vestire，经古法语 vestement 借入；英语这个词早于现代衣物名词 vest，不是现代 vest 加 -ment 才出现。',V+[['拉丁 vestimentum → 古法语 vestement → 英语 vestment','衣服 → 宗教仪式所穿服装']],'常用复数 vestments 说一套或多件宗教礼服。不同传统里的形制与颜色意义不同，先理解为仪式性服装即可。','ceremonial vestments；liturgical vestments；embroidered vestments。','vest 是日常背心等衣物；vestments 通常是宗教礼服，不等于任何正式西装。',('The exhibition includes embroidered vestments from the cathedral.','展览包含来自主教座堂的刺绣礼服。'),('The vestments were carefully stored after the service.','礼拜结束后，礼服被仔细收存起来。'),sources=['https://www.etymonline.com/word/vestment','https://www.oxfordlearnersdictionaries.com/definition/english/vestment']),
E('travesty','/ˈtrævəsti/','拙劣、荒唐的歪曲；滑稽模仿','外面还挂着原来的名字，里面却被改得荒唐，甚至完全违背应有的价值。','意大利 travestire 改装，经法语 travesti 假扮的进入英语；先有文学滑稽改写义，后常说严重歪曲。',V+[['意大利 tra- + vestire → travestire → 法语 travesti → 英语 travesty','换装、伪装 → 把严肃作品改成滑稽样子'],['英语 travesty 的扩展','荒唐的模仿、严重背离应有价值的事']],'a travesty of justice 是对正义的荒唐歪曲。并不是只要事情悲惨就叫 travesty；核心是名不副实、严重变形。','a travesty of；a travesty of justice；a literary travesty。','tragedy 是悲剧、惨事；travesty 是歪曲得离谱，常含愤怒或讽刺，两词并非近形同义。',('A vote with no genuine alternatives was a travesty of democracy.','没有真正可选方案的投票，是对民主的荒唐歪曲。'),('The play turns the solemn legend into a comic travesty.','这部戏把庄严的传说改成了滑稽模仿剧。'),sources=['https://www.etymonline.com/word/travesty','https://www.oxfordlearnersdictionaries.com/definition/english/travesty']),
E('transvestite','/trænzˈvestaɪt/','异装者〔旧称，现常被认为冒犯〕','旧文献里指穿着传统上归于另一性别服装的人；今天主要需要能看懂这个旧称。','20世纪借德语 Transvestit，德语借拉丁 trans- 跨越 + vestire 穿衣造词；不是古拉丁语已有一个现代身份类别。',V+[['德语 Transvestit〔借拉丁 trans- + vestire 构造〕→ 英语 transvestite','近代为异装现象造的旧称']],'现代称呼通常更常见 cross-dresser。这个旧词谈着装，不能直接等同 transgender 跨性别的身份概念；阅读历史材料时也要留意年代和作者用法。','the historical term transvestite；described as a transvestite in an old text。','穿着方式与性别认同不是同一概念。transvestite 如用来称呼当代个人，容易让人觉得过时或受冒犯。',('The archive preserves the word transvestite in the original caption.','档案保留了原图片说明中的旧词 transvestite。'),('The editor explains why transvestite is now often considered offensive.','编辑解释了为什么 transvestite 如今常被认为具有冒犯性。'),sources=['https://www.etymonline.com/word/transvestite','https://www.oxfordlearnersdictionaries.com/definition/english/transvestite','https://www.merriam-webster.com/dictionary/transvestite']),
]
