DEFERRED={'scansion':'诗歌格律的专门名词，扫描词的来源已在 scan 中说明。','descension':'较罕用下降名词，优先 descent。','condescendence':'较罕用名词，优先 condescension。','ascendency':'ascendancy 的另一拼写，复用常见拼写词条。','ascendent':'ascendant 的另一拼写，复用常见拼写词条。','descendent':'较少用变体，优先 descendant 与 descending。','diplomatics':'古文书研究专门名词，暂略。','diploblasty':'专门胚层分类术语，暂略。','diploidy':'专业倍性名词，基础概念由 diploid 说明。','diplonema':'专门细胞分裂阶段名，暂略。','diplophase':'专门生活史阶段名，暂略。','diplotene':'专门细胞分裂阶段名，暂略。','haplodiploid':'专门遗传系统形容词，暂略。','haplodiploidy':'专门遗传系统名词，暂略。','diplosis':'罕用专门词，暂略。','undine':'较冷门神话水精灵名称，暂略。','superabundance':'较罕用丰富名词，优先 abundance 与 overabundance。','superabundant':'较罕用派生形容词，优先 abundant。','undulatory':'较专门波动形容词，优先 undulate 与 undulation。','inundant':'罕用形容词，优先 inundate 与 inundation。','superabound':'罕用大量存在动词，优先 abound。','undulant':'较少用波状形容词，优先 undulating。','undulatus':'主要是拉丁形态或专门分类用语，暂略。','undulose':'较冷门生物形态形容词，暂略。'}
SCAND_ROOT=dict(id='C1268',meaning='攀登、上升；沿方向移动与超越',core='先想一个沿坡面移动的人：可以向上、向下，也可以越过原来的高度。',image='拉丁 scandere 攀登 → ascendere 向上、descendere 向下、transcendere 越过；scandere 的诗歌格律义另经中古英语成为 scan。',intro='scand- 在拉丁复合词里常变成 -scend-。ascend、descend 等保留空间方向，血统、地位、态度又借这些方向讲抽象关系。scan 虽然看起来很远，也来自这一词族；不过攀登与分析格律之间的具体联想并未完全确定。',forms='动词中常见 -scend，名词或形容词中常见 -scent、-scension；现代拼写对应并不意味着所有名词都由英语动词直接变成。ascent 是受 descend/descent 对应关系影响而形成，descent 则经法语借入。',branches=[['向上、地位上升','ascend, ascending, ascent, ascension, ascendancy, ascendant'],['向下与血统延续','descend, descending, descent, descendant'],['越过、超出','transcend, transcendent, transcendence, transcendental'],['自认为站得高、俯就别人','condescend, condescension, condescending, condescendingly'],['诗歌格律与扫描','scan, scanner, scanning']],contrasts='ascent 上升与 assent 同意同音；descent 下降与 dissent 异议同音。descendant 是后代，descending 说下降或降序。condescending 批评居高临下，不是普通善意帮助。',practice='各用 ascent 和 descent 描述一段山路；比较 a descendant 与 descending order；用一句话说明 condescending 的问题在态度而非帮助这个动作。',words=[w for w in ASSIGN['roots'][95]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][95]['family'])+ASSIGN['roots'][95]['unmatched'] if w in DEFERRED})
DIPL_ROOT=dict(id='C0331',meaning='双、折叠；证书与外交',core='一张折起来的正式文书，后来把证明资格、处理国与国关系这些意思连在一起。另一些词仍直接讲双。',image='希腊 diploos 双 → diploun 折成两层 → diplōma 折叠文书 → diploma；文书相关的 diplomatic → diplomat、diplomacy 一支。diploid、diplopia 另接双的组合形式。',intro='diploma、diplomatic 不是因为外交官拿了毕业证才有联系，而是共同接到正式文书的历史。diplomatic 的英语记录早于 diplomat。diploid 与 diplopia 则取双这一层意思，不是由现代 diploma 变出来。',forms='diploma、diplomacy 重读第二音节；diplomat 重读第一音节；diplomatic 重读 -mat-。diplomat 经法语借入，法语词本身与 diplomatique 的反构有关。',branches=[['正式证书','diploma'],['外交、外交人员与圆融表达','diplomatic, diplomacy, diplomat, diplomatically'],['双套与双重视觉','diploid, diplopia']],contrasts='diploma 是证书或某类资格，不能总等同学位 degree；diplomatic 既能说外交事务，也能说措辞圆融。diploid 是两套完整染色体，不是总共两条染色体。',practice='用 diploma 说一项学习资格，再用 diplomatic 说一段委婉表达；说明 diploid 里的双与 diplopia 里的双分别指什么。',words=[w for w in ASSIGN['roots'][96]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][96]['family'])+ASSIGN['roots'][96]['unmatched'] if w in DEFERRED})
SIL_ROOT=dict(id='C1341',meaning='安静、不作声',core='声音停下来：可以是房间里没有动静，也可以是人选择不说，或设备被调成不发声。',image='拉丁 silere 安静 → silens → silent；silere → silentium → 法语 silence → 英语 silence → silencer。',intro='silent 与 silence 共享拉丁 silere，却通过不同形态和借入路线进入英语。更远来源并不确定，无须给每个字母另编一个动作。silence 既是安静这个状态，也可以作使安静、使不再发声的动词。',forms='四个常见词的开头都读 /saɪl-/。silent 是形容词，silently 是方式副词；silencer 去掉 silence 末尾 e 后加 -er。',branches=[['安静的状态或使其停止','silence'],['不作声与无声地','silent, silently'],['降低声音的装置','silencer']],contrasts='silent 是不作声，quiet 可以只是声音小；silently 不等于 secretly 秘密地。silencer 通常降低声音，并不保证完全无声。',practice='分别描写一间安静房间、一个保持沉默的人、一个调成静音的手机；比较 remain silent 与 silence the phone。',words=list(ASSIGN['roots'][97]['family']),exclude={})
UND_ROOT=dict(id='C1583',meaning='波浪、涌流；满溢与起伏',core='水一层层涌起来：多到满出来是丰富，多过需要是多余，漫过某处是淹没，高低连续变化就是起伏。',image='拉丁 unda 波浪 → undare 涌流；abundare 满溢 → abound、abundant、abundance；redundare 再涌出 → redundant、redound；inundare 涌上 → inundation、inundate。',intro='这组词把波浪引向数量、影响与形状。abundance 可以是丰富资源，redundancy 可以是删掉的赘余，也可以是保留的备用能力。surround 的早期水流包围画面后来变成一般的环绕；不能只按现代 round 的样子判断来源。',forms='abound 与 abundance 的元音和结尾不同，是同源词各自发展的结果。inundation 与 undulation 的英语名词比相应常用动词早，不能看到 -ation 就认定一定先有英语动词。',branches=[['多到充足','abound, abundant, abundance, abundantly'],['超过需要','overabundance, redundant, redundancy'],['涌来、漫过','inundate, inundation'],['连续波浪状','undulate, undulation'],['效果回到某方与环绕','redound, surround']],contrasts='abundance 常是丰富，overabundance 明确是过多。redundant 在文章里常表示多余，在系统里也可以表示有意设置的备用。redound to one’s credit 是增光，与 rebound 反弹不同。',practice='分别用 abundant、redundant、inundated 描述资源、句子和邮箱；解释为什么技术上的 redundancy 未必是坏事；描写一条高低起伏的路。',words=[w for w in ASSIGN['roots'][98]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][98]['family'])+ASSIGN['roots'][98]['unmatched'] if w in DEFERRED})
VEST_ROOT=dict(id='C1627',meaning='衣服、穿衣；赋予、投入与剥离',core='衣服穿到身上，可以标示一个人的职位；抽象地说，权力与权益也能归到某人身上。',image='拉丁 vestis 衣服、vestire 穿衣 → vest、vestment；investire 披上 → invest、investiture；金融 invest 很可能另受同源意大利用法影响；desvestir 脱去 → divest。',intro='vest- 的衣服画面能帮助理解授职与剥离，却不能代替全部历史。投资义很可能经过同源意大利语的特殊用法，不宜编成把钱穿在身上。英语 vest 的动词和名词也有不同借入线，动词出现更早。',forms='invest、divest、investiture 的主重音都落在 vest。investment 是投入或投资，investiture 是授职授勋仪式。travesty 经意大利语、法语明显改形；transvestite 则是近代德语借拉丁成分造出的旧称。',branches=[['衣物与仪式服装','vest, vestment'],['权利归属','vested, vesting'],['投入资源','invest, investment, investor, investing, invested'],['再次投入','reinvest, reinvestment'],['脱去、剥离','divest, divestment'],['授职与换装支线','investiture, travesty, transvestite']],contrasts='invest 是投入，divest 是退出或剥离；vested interest 是既有的直接利益，invested 可以说投入了感情。travesty 是荒唐歪曲，不是 tragedy 悲剧的变体。',practice='用 invest 分别说钱和时间；比较 investment 与 investiture；用 invested in 说一个让自己投入感情的故事；说明 vesting 与资金到账并不相同。',words=list(ASSIGN['roots'][99]['family']),exclude={})
